  function yB(phi){ var p=rad(phi); return K.Oy - K.a*Math.cos(p) - Math.sqrt(K.b*K.b - Math.pow(K.a*Math.sin(p),2)); }
  var yOpen = yB(K.phiOpen);
  function travel(phi){ return yOpen - yB(phi); }
  function dyd(phi){ var p=rad(phi), s=Math.sin(p), c=Math.cos(p); return K.a*s + K.a*K.a*s*c/Math.sqrt(K.b*K.b - K.a*K.a*s*s); }
  function MA(phi){ return K.L / dyd(phi); }
  function force(phi, hand){ return (hand||K.hand) * K.eta * MA(phi); }
  var Z = {lowerTop:66, upperBottom:92, contact:26, pickStop:35.5, frameTravel:8, recess:5.5};
  function phiForTravel(t){ var lo=K.phiEnd, hi=K.phiOpen; for(var i=0;i<60;i++){ var m=(lo+hi)/2; if(travel(m) > t) lo=m; else hi=m; } return (lo+hi)/2; }
  var psiPick = phiForTravel(Z.pickStop) - K.off;
  var SIZES = [
    {id:'s50', label:'50 × 50', code:'5050', W:50, H:50},
    {id:'s63', label:'63.5 × 63.5', code:'6363', W:63.5, H:63.5},
    {id:'r53', label:'53 × 80', code:'5380', W:53, H:80},
    {id:'r65', label:'65 × 90', code:'6590', W:65, H:90}];
  function fitA4(w,h){ w+=1; h+=1; return Math.max(Math.floor(210/w)*Math.floor(297/h), Math.floor(210/h)*Math.floor(297/w)); }
  function dims(s){
    var X = Math.max(s.W, s.H), Z = Math.min(s.W, s.H), r = 4, P = 2*(X+Z) - 8*r + 2*Math.PI*r, crimpPre = 7*P;
    return { W:X, H:Z, X:X, Z:Z, r:r, P:P, crimpPre:crimpPre, peak:2.2*crimpPre, upSpr:0.29*crimpPre, pickSpr:100,
      paper:[X+12,Z+12], safe:[X-6,Z-6], back:[X-1.4,Z-1.4], mag:[X-4,Z-4],
      plug:[X+0.30,Z+0.30], upIn:[X+0.35,Z+0.35], upOut:[X+30,Z+30], body:[X+32,Z+32],
      pickPed:[X-0.5,Z-0.5], pickIn:[X+0.6,Z+0.6], pickRec:[X+12.5,Z+12.5], lowOut:[X+32,Z+32],
      crimpPed:[X-4.5,Z-4.5], crimpIn:[X+0.45,Z+0.45], perA4: fitA4(X+12,Z+12) };
  }
  function f2(n){ return String(+n.toFixed(2)); }
  function pair(a){ return f2(a[0]) + ' × ' + f2(a[1]); }
  function kN(n){ return (n/1000).toFixed(1) + ' kN'; }
  var STEPS = [
    {t:'Base and feet', s:'Fit 6 rubber feet to the base plate. Put the base on a flat bench and check it rocks on none of them.',
      ul:['Feet: M6 studs into tapped holes, hand tight','Check the station area with a straightedge and feeler gauge'], chk:'Base flat within 0.1 mm across the station area'},
    {t:'Slide guides', s:'Lay the two guide rails parallel, put the keepers on top and screw both down together, then fit the two stop blocks on the back keeper.',
      ul:['M5 × 20 countersunk screws through keeper and rail, 6 N·m','Set rail spacing with the die table itself plus 0.05 mm shim','Stop blocks: 2 × M5 × 35 each, through keeper and rail'], chk:'Rails parallel within 0.05 mm over 400 mm'},
    {t:'Die table', s:'Slide the die table in under the keepers. Fit the stop pin, the M6 ball plunger and the two push knobs (end faces).',
      ul:['Table should run end to end with fingertip force and no rock','Ball plungers click at both stations'], chk:'Running clearance 0.03–0.05 mm, no lift at the ends'},
    {t:'Columns', s:'Press the two columns into the base (H7/p6) and pull them down with M10 screws and Ø32 washers from below.',
      ul:['Support the base on the press bed directly under each bore','Loctite 243 on the M10 screws, 40 N·m'], chk:'Columns square to the base within 0.05 per 100 mm'},
    {t:'Ram', s:'Press the bushings into the ram, fit the clevis and die holder, screw in the return rods, then slide the ram down onto the columns.',
      ul:['Bushings flush with the ram underside','Clevis: 2 × M5 into the 2 mm locating pocket','Die holder: 4 × M5 low-head, 6 N·m; bumpers: 2 × M6 on the ram top'], chk:'Ram slides the full column length under its own weight'},
    {t:'Crown and return springs', s:'Lower the crown over the column tops and the return rods. Torque the column nuts, then fit the return springs, washers and nylock nuts, and screw the handle-stop buffer into the front column top.',
