962	    shim:{name:'Depth shim pack', layer:'Die set · upper', qty:'1 per set', mat:'Stainless shims 0.1 / 0.2 / 0.5', dims:'Ø40 with Ø16.5 and Ø4.2 holes', note:'Set so the crimp finishes with the handle 5–10° above horizontal. Laser-mark the value on the die.'},
