970	    frameA:{name:'Pickup frame', layer:'Die set · lower A', qty:'1 per set', mat:'Cr12MoV 58–60 HRC (MP-207)', dims:`Opening ${P(d.pickIn)}; film recess ${P(d.pickRec)} × 0.6; outside ${P(d.lowOut)}; h 18; travel 8`, note:'Centres the shell and the film. It drops 8 mm onto the shoe as the upper frame pushes the film down around the shell.'},
