972	    pedB:{name:'Crimp pedestal', layer:'Die set · lower B', qty:'1 per set', mat:'Cr12MoV 58–60 HRC (MP-208)', dims:`${P(d.crimpPed)}, R2.5, h 17`, note:'Smaller than the back plate, which leaves room for the shell edge to roll under the back.'},
973	    frameB:{name:'Crimp frame', layer:'Die set · lower B', qty:'1 per set', mat:'Cr12MoV 58–60 HRC (MP-209)', dims:`Opening ${P(d.crimpIn)} with 1.2 × 30° lead-in; outside ${P(d.lowOut)}; h 18; travel 8`, note:'The lead-in folds the film skirt under the shell edge as the shell enters. It bottoms on the shoe at 8 mm.'},
974	    sprB:{name:'Crimp springs', layer:'Die set · lower B', qty:'8 per set', mat:'ISO 10243 red or yellow, Ø10 hole', dims:`Total preload ≈ ${k(d.crimpPre)} (estimate)`, note:'Stiffer than the upper frame springs. That is what makes the two-stroke sequence work.'}
