983	  stop:{name:'Station stop block', layer:'Frame', qty:'2', mat:'C45 + M6 × 0.75 stop screw (MP-104)', dims:'30 × 27 × 16', note:'Adjust so each station sits under the ram centre within ±0.05 mm, then lock.'},
984	  post:{name:'Column', layer:'Frame', qty:'2', mat:'GCr15 / 52100, 58–62 HRC, hard chrome', dims:'Ø25 h6 × 158 + Ø20 spigots, 206.5 long (MP-107)', note:'Ø20 spigot pressed into the base and clamped from below with M10 + Ø32 washer; M16 × 1.5 nut on top of the crown.'},
