    // pickup stop marker
    sv('line',{x1:xs(MP.Z.pickStop),x2:xs(MP.Z.pickStop),y1:ys(0),y2:ys(0)-10,'class':'axis'},svg);
    var ps=sv('text',{x:xs(MP.Z.pickStop),y:ys(0)-14,'text-anchor':'middle','class':'lbl'},svg); ps.textContent='stroke 1 ends';
    var last=samples[samples.length-1];
    sv('circle',{cx:xs(last.t),cy:ys(last.f),r:4.5,'class':'dot'},svg);
    var el1=sv('text',{x:xs(last.t)+10,y:ys(last.f)+4,'class':'lblk'},svg); el1.textContent=(last.f/1000).toFixed(1)+' kN available';
    refG = sv('g',{},svg);
    xh = sv('line',{x1:0,x2:0,y1:m.t,y2:CH-m.b,'class':'xh',visibility:'hidden'},svg);
    dotEl = sv('circle',{cx:-20,cy:-20,r:5,'class':'dot'},svg);
    drawRef(); setPoseMarker(MP.K.phiOpen);
    var hit=sv('rect',{x:m.l,y:m.t,width:CW-m.l-m.r,height:CH-m.t-m.b,fill:'transparent'},svg);
    var tip=document.getElementById('ctip'), box=document.getElementById('chartBox');
    function move(ev){ var r=svg.getBoundingClientRect(); var x=(ev.clientX-r.left)*CW/r.width; var t=(x-m.l)/(CW-m.l-m.r)*40; var best=samples[0], bd=1e9; samples.forEach(function(s){ var dd=Math.abs(s.t-t); if(dd<bd){bd=dd;best=s;} });
      xh.setAttribute('x1',xs(best.t)); xh.setAttribute('x2',xs(best.t)); xh.setAttribute('visibility','visible');
      tip.hidden=false; tip.textContent=''; [['Travel',best.t.toFixed(1)+' mm'],['Handle',best.psi.toFixed(1)+'°'],['MA','×'+best.ma.toFixed(1)],['Force',(best.f/1000).toFixed(2)+' kN']].forEach(function(p){ var dv=document.createElement('div'); dv.textContent=p[0]+'  '+p[1]; tip.appendChild(dv); });
      var br=box.getBoundingClientRect(); var px=ev.clientX-br.left+box.scrollLeft+14, py=ev.clientY-br.top+14; if(px>box.clientWidth-150) px-=170; tip.style.left=px+'px'; tip.style.top=py+'px'; }
    hit.addEventListener('pointermove',move); hit.addEventListener('pointerdown',move);
    hit.addEventListener('pointerleave',function(){ tip.hidden=true; xh.setAttribute('visibility','hidden'); });
  }
  function drawRef(){
    if(!refG) return; refG.innerHTML=''; var d=MP.dims(MP.cur); var tEnd=samples[samples.length-1].t;
    sv('line',{x1:xs(MP.Z.contact),x2:xs(tEnd),y1:ys(d.peak),y2:ys(d.peak),'class':'ref'},refG);
    var t=sv('text',{x:xs(tEnd)+10,y:ys(d.peak)+4,'class':'lbl'},refG); t.textContent=MP.cur.label+' needs ≈ '+(d.peak/1000).toFixed(1)+' kN';
  }
  function setPoseMarker(phi){ if(!dotEl) return; dotEl.setAttribute('cx',xs(MP.travel(phi))); dotEl.setAttribute('cy',ys(MP.force(phi))); }
  document.addEventListener('mp:pose',function(e){ setPoseMarker(e.detail.phi); });

  function onSize(){ renderDieTable(); renderCons(); drawRef();
    Array.prototype.forEach.call(seg.querySelectorAll('button'),function(b){ b.setAttribute('aria-pressed', String(b.getAttribute('data-size')===MP.cur.id)); }); }
  document.addEventListener('mp:size', onSize);
  renderDieTable(); renderCons(); drawChart();

  setTimeout(function(){ var m=document.getElementById('stageMsg'); if(m && m.isConnected && !document.querySelector('#stage canvas')) m.textContent='The 3D model needs WebGL and access to cdn.jsdelivr.net. It did not load here; the rest of the build pack below still works.'; }, 12000);

  // CSV copy
  document.getElementById('copyBom').addEventListener('click',function(){
    var csv = 'Group,Item,Qty,Make/buy,Spec\n' + BOM.map(function(r){ return r.map(function(c){ return '"'+String(c).replace(/"/g,'""')+'"'; }).join(','); }).join('\n');
    var ta=document.getElementById('scadOut');
    function fallback(){ ta.hidden=false; ta.value=csv; ta.focus(); ta.select(); toast('Clipboard blocked. The CSV is selected in the box below; copy it from there.'); }
    try{ navigator.clipboard.writeText(csv).then(function(){ toast('BOM copied as CSV ('+BOM.length+' rows)'); }, fallback); }catch(e){ fallback(); }
  });
})();
</script>

<script type="importmap">{"imports":{"three":"https://cdn.jsdelivr.net/npm/three@0.160.0/build/three.module.js","three/addons/":"https://cdn.jsdelivr.net/npm/three@0.160.0/examples/jsm/"}}</script>
<script type="module">
import * as THREE from 'three';
import { OrbitControls } from 'three/addons/controls/OrbitControls.js';
import { RoomEnvironment } from 'three/addons/environments/RoomEnvironment.js';

const MP = window.MP, K = MP.K;
const D2R = Math.PI/180;
const stage = document.getElementById('stage');
const msg = document.getElementById('stageMsg');

try {

const renderer = new THREE.WebGLRenderer({antialias:true});
renderer.setPixelRatio(Math.min(window.devicePixelRatio||1, 2));
renderer.outputColorSpace = THREE.SRGBColorSpace;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.2;
stage.insertBefore(renderer.domElement, stage.firstChild);
msg.remove();

const scene = new THREE.Scene();
const pmrem = new THREE.PMREMGenerator(renderer);
scene.environment = pmrem.fromScene(new RoomEnvironment(), 0.04).texture;
const camera = new THREE.PerspectiveCamera(32, 1, 5, 6000);
const controls = new OrbitControls(camera, renderer.domElement);
controls.enableDamping = true; controls.dampingFactor = 0.08; controls.minDistance = 150; controls.maxDistance = 2600;
const sun = new THREE.DirectionalLight(0xffffff, 1.4); sun.position.set(300, 700, 500); scene.add(sun);
scene.add(new THREE.HemisphereLight(0xffffff, 0x3a3a3a, 0.6));
const ground = new THREE.Mesh(new THREE.CircleGeometry(900, 64), new THREE.MeshStandardMaterial({color:0xcccccc, roughness:1, metalness:0}));
ground.rotation.x = -Math.PI/2; ground.position.y = -0.5; scene.add(ground);

function css(v){ return getComputedStyle(document.documentElement).getPropertyValue(v).trim(); }
let ACC = new THREE.Color('#8A6510');
function applyTheme(){
  try{ scene.background = new THREE.Color(css('--stage')); ground.material.color = new THREE.Color(css('--sunk')); ACC = new THREE.Color(css('--accent')); }catch(e){}
  refreshHighlight();
}
matchMedia('(prefers-color-scheme: dark)').addEventListener('change', applyTheme);
new MutationObserver(applyTheme).observe(document.documentElement, {attributes:true, attributeFilter:['data-theme']});

// ---------- materials ----------
function std(c, m, r, extra){ return new THREE.MeshStandardMaterial(Object.assign({color:c, metalness:m, roughness:r, side:THREE.DoubleSide, envMapIntensity:1.5}, extra||{})); }
const MAT = {
  powder: std(0x2a2d31, 0.15, 0.62), gold: std(0xc9a13b, 0.8, 0.32), chrome: std(0xe4e7ea, 0.85, 0.16),
  black: std(0x1f2226, 0.55, 0.42), steel: std(0xb4bac1, 0.7, 0.34), die: std(0xd0d5da, 0.72, 0.28), dieF: std(0xbcc3ca, 0.68, 0.33),
  bronze: std(0xb3894a, 0.9, 0.35), rubber: std(0x161616, 0, 0.9), red: std(0xd3262e, 0.05, 0.55),
  sprG: std(0x3e9b4f, 0.4, 0.45), sprB: std(0x2f6fb5, 0.4, 0.45), sprR: std(0xc8302b, 0.4, 0.45), sprS: std(0xcfd4d9, 0.9, 0.3),
  ure: std(0xd99a2b, 0, 0.5), knob: std(0x232323, 0.1, 0.55), uhmw: std(0xeeeeea, 0, 0.7),
  tin: std(0xdde1e5, 0.75, 0.25), backP: std(0x2c2c2c, 0.1, 0.5)
};

// ---------- photo texture ----------
function photoTexture(){
  const c = document.createElement('canvas'); c.width = c.height = 512; const g = c.getContext('2d');
  const sky = g.createLinearGradient(0,0,0,330); sky.addColorStop(0,'#2b2d6e'); sky.addColorStop(0.45,'#c0466f'); sky.addColorStop(0.8,'#f39a4c'); sky.addColorStop(1,'#ffd27a');
  g.fillStyle = sky; g.fillRect(0,0,512,330);
  g.fillStyle = '#fff1c4'; g.beginPath(); g.arc(300,260,52,0,Math.PI*2); g.fill();
  g.fillStyle = '#5b2a52'; g.beginPath(); g.moveTo(0,300); g.lineTo(90,210); g.lineTo(170,280); g.lineTo(250,190); g.lineTo(360,300); g.lineTo(430,230); g.lineTo(512,290); g.lineTo(512,340); g.lineTo(0,340); g.fill();
  g.fillStyle = '#2d1838'; g.beginPath(); g.moveTo(0,330); g.lineTo(120,270); g.lineTo(220,330); g.lineTo(330,262); g.lineTo(512,330); g.lineTo(512,345); g.lineTo(0,345); g.fill();
  const sea = g.createLinearGradient(0,330,0,512); sea.addColorStop(0,'#e0794f'); sea.addColorStop(1,'#1d2a55'); g.fillStyle = sea; g.fillRect(0,335,512,177);
  g.strokeStyle = 'rgba(255,230,170,.7)'; g.lineWidth = 3; for(let i=0;i<9;i++){ const y = 350 + i*16; g.beginPath(); g.moveTo(300-60+i*4, y); g.lineTo(300+60-i*4, y); g.stroke(); }
  g.fillStyle='rgba(255,255,255,.9)'; g.font='600 34px sans-serif'; g.textAlign='center'; g.fillText('GOA 2026', 256, 470);
  const t = new THREE.CanvasTexture(c); t.colorSpace = THREE.SRGBColorSpace; t.anisotropy = 4; return t;
}
const PHOTO = photoTexture();

// ---------- geometry helpers (each returns {geo, scad}) ----------
const f = n => +(+n).toFixed(3);
function rrPath(p, w, d, r, cy){ cy = cy||0; r = Math.min(r, w/2-0.01, d/2-0.01); const hw=w/2, hd=d/2;
  p.moveTo(-hw+r, cy-hd); p.lineTo(hw-r, cy-hd); p.absarc(hw-r, cy-hd+r, r, -Math.PI/2, 0, false); p.lineTo(hw, cy+hd-r);
  p.absarc(hw-r, cy+hd-r, r, 0, Math.PI/2, false); p.lineTo(-hw+r, cy+hd); p.absarc(-hw+r, cy+hd-r, r, Math.PI/2, Math.PI, false);
  p.lineTo(-hw, cy-hd+r); p.absarc(-hw+r, cy-hd+r, r, Math.PI, 1.5*Math.PI, false); return p; }
const G = {
  box(x,y,z){ return {geo:new THREE.BoxGeometry(x,y,z), scad:`cube([${f(x)},${f(z)},${f(y)}],center=true);`}; },
  cyl(r,h,axis='y',seg=40){ const g = new THREE.CylinderGeometry(r,r,h,seg); if(axis==='x') g.rotateZ(Math.PI/2); if(axis==='z') g.rotateX(Math.PI/2);
    const c = `cylinder(r=${f(r)},h=${f(h)},center=true,$fn=${seg});`; return {geo:g, scad: axis==='y'?c : axis==='x'?`rotate([0,90,0]) ${c}`:`rotate([90,0,0]) ${c}`}; },
  rr(w,d,r,h,hole){ const s = rrPath(new THREE.Shape(), w, d, r); let hs='';
    if(hole){ const oz = hole.oz||0; s.holes.push(rrPath(new THREE.Path(), hole.w, hole.d, hole.r, -oz));
      const hr=Math.min(hole.r, hole.w/2-0.01, hole.d/2-0.01); hs = `translate([0,${f(-oz)}]) offset(r=${f(hr)}) square([${f(hole.w-2*hr)},${f(hole.d-2*hr)}],center=true);`; }
    const g = new THREE.ExtrudeGeometry(s, {depth:h, bevelEnabled:false, curveSegments:8}); g.rotateX(-Math.PI/2); g.translate(0,-h/2,0);
    const rr = Math.min(r, w/2-0.01, d/2-0.01);
    const outer = `offset(r=${f(rr)}) square([${f(w-2*rr)},${f(d-2*rr)}],center=true);`;
    return {geo:g, scad:`translate([0,0,${f(-h/2)}]) linear_extrude(height=${f(h)}) ${hole?`difference(){${outer} ${hs}}`:outer}`}; },
  spring(R, wire, h, turns){ const curve = new (class extends THREE.Curve{ getPoint(t, tg=new THREE.Vector3()){ const a = t*turns*Math.PI*2; return tg.set(R*Math.cos(a), h*t - h/2, R*Math.sin(a)); } })();
    const g = new THREE.TubeGeometry(curve, Math.max(60, turns*28), wire, 6, false);
    return {geo:g, scad:`linear_extrude(height=${f(h)},center=true,twist=${-360*turns},slices=${turns*24}) translate([${f(R)},0]) circle(r=${f(wire)},$fn=8);`}; }
};

// ---------- scene graph ----------
const root = new THREE.Group(); scene.add(root);
const gStatic = new THREE.Group(), gSlide = new THREE.Group(), gRam = new THREE.Group(), gHandle = new THREE.Group(), gLinks = new THREE.Group();
root.add(gStatic, gSlide, gRam, gHandle, gLinks);
const gFrameA = new THREE.Group(), gFrameB = new THREE.Group(), gDieSlide = new THREE.Group(); gSlide.add(gFrameA, gFrameB, gDieSlide);
const gDieRam = new THREE.Group(), gUpFrame = new THREE.Group(); gRam.add(gDieRam); gDieRam.add(gUpFrame);

const parts = [];   // {mesh, base, ex, step, layer, id, die}
const INFO = {};
const pickables = [];
function part(parent, id, g, mat, pos, o={}){
  const mesh = new THREE.Mesh(g.geo, mat.clone());
  mesh.position.set(pos[0], pos[1], pos[2]);
  if(o.rot) mesh.rotation.set(o.rot[0]*D2R, o.rot[1]*D2R, o.rot[2]*D2R);
  mesh.userData = {id, scad:g.scad};
  parent.add(mesh);
  const p = {mesh, base:mesh.position.clone(), ex:new THREE.Vector3(...(o.ex||[0,0,0])), step:o.step||1, layer:o.layer||'frame', id, die:!!o.die, spring:o.spring||null, baseScaleY:1};
  parts.push(p); pickables.push(mesh); return p;
}
function info(id, o){ INFO[id] = o; }

// ---- static frame ----
const L1 = {layer:'frame'};
part(gStatic,'base',G.box(460,12,260),MAT.powder,[0,12,0],{...L1,step:1});
part(gStatic,'base',G.box(140,12,210),MAT.powder,[0,12,235],{...L1,step:1});
[[-200,-110],[200,-110],[-200,110],[200,110],[-55,320],[55,320]].forEach(p=>part(gStatic,'foot',G.cyl(12,6),MAT.rubber,[p[0],3,p[1]],{...L1,step:1,ex:[0,-40,0]}));
[-82,82].forEach(z=>{ part(gStatic,'rail',G.box(460,12.05,14),MAT.steel,[0,24.025,z],{...L1,step:2,ex:[0,40,0]}); });
[-80,80].forEach(z=>{ part(gStatic,'keeper',G.box(460,4,20),MAT.black,[0,32.05,z],{...L1,step:2,ex:[0,70,0]}); });
[-101,101].forEach(x=>{ const e={...L1,step:2,ex:[0,90,0]}, s=Math.sign(x);
  part(gStatic,'stop',G.box(30,16,27),MAT.black,[x,42.05,-76.5],e);
  part(gStatic,'stop',G.cyl(3,6,'x',12),MAT.steel,[s*86,42,-68],e);
  part(gStatic,'stop',G.cyl(5,4,'x',6),MAT.steel,[s*118,42,-68],e); });
[-105,105].forEach(z=>{ const e={...L1,step:4,ex:[0,30,z>0?140:-140]};
  part(gStatic,'post',G.cyl(12.5,158,'y',48),MAT.chrome,[0,97,z],e);
  part(gStatic,'post',G.cyl(10,25,'y',40),MAT.chrome,[0,188.5,z],e);
  part(gStatic,'post',G.cyl(8,16,'y',32),MAT.steel,[0,209,z],e); });
part(gStatic,'crown',G.rr(80,250,6,25,{w:38,d:66,r:5,oz:13}),MAT.black,[0,188.5,0],{...L1,step:6,ex:[0,330,0]});
