const { chromium } = require('playwright');
const fs = require('fs');
(async () => {
  const dir = process.argv[2];
  const html = '<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"></head><body>' + fs.readFileSync(dir + '/magpress-m4.html','utf8') + '</body></html>';
  fs.writeFileSync(dir + '/_t.html', html);
  const browser = await chromium.launch({args:['--use-gl=swiftshader','--enable-webgl','--ignore-gpu-blocklist']});
  const page = await browser.newPage({viewport:{width:1500,height:1400}, deviceScaleFactor: 2});
  const errs = [];
  page.on('console', m => { if (m.type()==='error') errs.push(m.text()); });
  page.on('pageerror', e => errs.push('pageerror: '+e.message));
  await page.goto('file://' + dir + '/_t.html');
  await page.waitForTimeout(5000);
  await page.click('#resetCycle');
  await page.addStyleTag({content: '.views,#caption,#tip{display:none!important} .bench{grid-template-columns:1fr!important} .rail{display:none!important} #stage{height:1150px!important;width:620px!important}'});
  await page.waitForTimeout(800);
  const stage = await page.$('#stage');
  await page.mouse.move(1450, 5);
  await page.evaluate(() => window.MP.camTo([1408, 1050, 1684], [0, 220, 60]));
  await page.waitForTimeout(1200);
  await stage.screenshot({path: dir + '/cover_assembled.png'});
  await page.$eval('#explode', e => { e.value = 70; e.dispatchEvent(new Event('input')); });
  await page.evaluate(() => window.MP.camTo([1650, 1420, 1960], [0, 400, 60]));
  await page.mouse.move(1450, 5); await page.waitForTimeout(1200);
  await stage.screenshot({path: dir + '/cover_exploded.png'});
  console.log('errors:', errs.length ? errs.join('\n') : 'none');
  await browser.close();
